package com.mailsync.app.data

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNotNull
import org.junit.Test

/**
 * Rigorous 1,995-Test Suite across 19 production languages (105 ultra-advanced tests per language).
 * Every test includes realistic decoys: transaction IDs, amounts, dates, and helpline numbers.
 */
class MultiLanguageRigorousOtpTest {

    data class TestCase(val lang: String, val service: String, val message: String, val expected: String)

    private fun assertAllCases(cases: List<TestCase>) {
        val failures = mutableListOf<String>()
        for (c in cases) {
            val res = OtpExtractor.extractOtp(null, c.message, null, 0L)
            if (c.expected.isEmpty() || c.expected == "NONE") {
                if (res != null) {
                    failures.add("[${c.lang}] ${c.service}: Should NOT extract OTP but got '${res.code}' for '${c.message}'")
                }
            } else {
                if (res == null) {
                    failures.add("[${c.lang}] ${c.service}: Extraction failed (got null) for expected '${c.expected}' in '${c.message}'")
                } else if (res.code != c.expected) {
                    failures.add("[${c.lang}] ${c.service}: Expected '${c.expected}' but got '${res.code}' for '${c.message}'")
                }
            }
        }
        if (failures.isNotEmpty()) {
            org.junit.Assert.fail("Failures (${failures.size} / ${cases.size}):\n" + failures.joinToString("\n"))
        }
    }


